if(!LANGS.includes(lang)){const n=(navigator.language||"en").slice(0,2).toLowerCase();lang=LANGS.includes(n)?n:"en"}
const t=k=>(translations[lang]&&translations[lang][k])||translations.en[k]||k;
const dnCache={};
function nm(code){try{const dn=dnCache[lang]||(dnCache[lang]=new Intl.DisplayNames([lang],{type:"region"}));return dn.of(code)||BY_CODE[code].en}catch(e){return BY_CODE[code].en}}
function applyLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.body.dir=lang==="ar"?"rtl":"ltr";$$("[data-i18n]").forEach(el=>{el.innerHTML=t(el.dataset.i18n)});$$("[data-i18n-ph]").forEach(el=>{el.placeholder=t(el.dataset.i18nPh)});$("#languageSelect").value=lang}

/* ---------- state ---------- */
const S={code:"TN",desc:"",hover:null,latlng:{}};
let wish=store.get("discoverWish",[]).filter(c=>BY_CODE[c]);
let memoryData="",postPhotoData="",taskState=[false,false,false,false],renderToken=0,feedFilter="all";
const getBook=()=>store.get("discoverBook",[]).filter(e=>BY_CODE[e.code]);

/* ---------- toast ---------- */
function toast(msg){const el=$("#toast");el.textContent=msg;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2800)}

/* ---------- network helpers (Wikipedia, REST Countries) ---------- */
const memo=new Map();
function jget(url){if(memo.has(url))return memo.get(url);const p=fetch(url).then(r=>{if(!r.ok)throw Error(r.status);return r.json()});memo.set(url,p);p.catch(()=>memo.delete(url));return p}
const wikiSummary=(l,title)=>jget(`https://${l}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(title.replace(/ /g,"_"))}?redirect=true`);
async function wikiSearch(l,q,n=8){const u=`https://${l}.wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrsearch=${encodeURIComponent(q)}&gsrlimit=${Math.min(n*2,18)}&gsrnamespace=0&prop=pageimages%7Cextracts&piprop=thumbnail&pithumbsize=600&exintro=1&explaintext=1&exsentences=2&exlimit=max`;const d=await jget(u);return Object.values(d.query?.pages||{}).sort((a,b)=>a.index-b.index)}
const getFacts=code=>jget(`https://restcountries.com/v3.1/alpha/${code}?fields=capital,region,subregion,population,languages,currencies,area,latlng`).then(d=>Array.isArray(d)?d[0]:d);
const TOUR_Q={en:"tourist attractions",fr:"attractions touristiques",ar:"معالم سياحية",es:"atracciones turísticas",de:"Sehenswürdigkeiten",it:"attrazioni turistiche"};
const FOOD_Q={en:"traditional dish national cuisine",fr:"plat traditionnel cuisine",ar:"طبق تقليدي مطبخ",es:"plato tradicional cocina",de:"traditionelles Gericht Küche",it:"piatto tradizionale cucina"};
const BAD=/^(list of|lists of|tourism|turismo|tourisme|tourismus|liste|elenco|lista|السياحة|قائمة|portal|category)/i;
const searchName=(code,l)=>l==="en"?(WIKI_EN[code]||BY_CODE[code].en).replace(/\s*\(.*\)/,""):nm(code);
const summaryName=(code,l)=>l==="en"?(WIKI_EN[code]||BY_CODE[code].en):nm(code);
function getAttractions(code,l=lang){const key=`att:${code}:${l}`;if(memo.has(key))return memo.get(key);const name=searchName(code,l),nn=norm(name);const p=(async()=>{const pages=await wikiSearch(l,`${TOUR_Q[l]} ${name}`,8).catch(()=>[]);const out=pages.filter(x=>x.thumbnail&&x.extract&&x.extract.length>40&&!BAD.test(x.title)&&norm(x.title)!==nn).map(x=>({title:x.title,text:short(x.extract,115),img:x.thumbnail.source}));if(out.length<3&&l!=="en")return getAttractions(code,"en");return out.slice(0,6)})();memo.set(key,p);return p}
function getFood(code,l=lang){const key=`food:${code}:${l}`;if(memo.has(key))return memo.get(key);const name=searchName(code,l);const p=(async()=>{const pages=await wikiSearch(l,`${FOOD_Q[l]} ${name}`,6).catch(()=>[]);const out=pages.filter(x=>x.extract&&x.extract.length>30&&!BAD.test(x.title)).map(x=>({emoji:"🍽️",title:x.title,text:short(x.extract,90),img:x.thumbnail?.source})).slice(0,4);if(out.length<2&&l!=="en")return getFood(code,"en");return out})();memo.set(key,p);return p}
async function getDesc(code){const cur=CURATED[code];if(cur&&lang==="en")return cur.desc;try{const s=await wikiSummary(lang,summaryName(code,lang));if(s.extract)return short(s.extract,230)}catch(e){if(lang!=="en"){try{const s=await wikiSummary("en",summaryName(code,"en"));if(s.extract)return short(s.extract,230)}catch(e2){}}}return cur?.desc||t("fallbackDesc")}
const canLoad=u=>new Promise(r=>{const i=new Image();i.onload=()=>r(true);i.onerror=()=>r(false);i.src=u});
async function getCover(code){const cur=CURATED[code];if(cur){const u=IMAGE(cur.cover,1800);if(await canLoad(u))return u}const a=await getAttractions(code).catch(()=>[]);return a[0]?.img||null}

/* ---------- global image fallbacks ---------- */
document.addEventListener("error",e=>{const img=e.target;if(!(img instanceof HTMLImageElement))return;
  if(img.classList.contains("flag")){const s=document.createElement("span");s.className="flag-emoji";s.textContent=flagEmoji(img.dataset.code);img.replaceWith(s);return}
  if(img.dataset.fix&&!img.dataset.tried){img.dataset.tried="1";fixImage(img);return}
  img.style.display="none"},true);
async function fixImage(img){try{const pages=await wikiSearch("en",img.dataset.fix,3);const p=pages.find(x=>x.thumbnail);if(p)img.src=p.thumbnail.source;else img.style.display="none"}catch(e){img.style.display="none"}}

/* ---------- selected country UI ---------- */
function renderSelected(){const c=S.code,on=wish.includes(c);
  $("#selectedCountry").innerHTML=`<div class="panel-kicker">${t("selectedDest")}</div><div class="sel-row">${flagImg(c,"lg")}<h3>${esc(nm(c))}</h3></div><p id="selDesc">${esc(S.desc)}</p><div class="sel-actions"><button type="button" class="chip-btn" data-act="wish" aria-pressed="${on}">${on?"♥":"♡"} ${on?t("wishRemove"):t("wishAdd")}</button><button type="button" class="chip-btn" data-act="share">↗ ${t("share")}</button></div>`}
const chip=c=>`<button type="button" data-code="${c}">${flagImg(c)}<span>${esc(nm(c))}</span></button>`;
function renderWish(){$("#wishlist").innerHTML=wish.length?wish.map(chip).join(""):`<p class="wish-empty">${t("wishlistEmpty")}</p>`}
function renderChips(){$("#popularCountries").innerHTML=POPULAR.map(chip).join("");renderWish()}
function populateSelect(){const sel=$("#countrySelect");sel.innerHTML=COUNTRY_LIST.map(c=>[c.code,nm(c.code)]).sort((a,b)=>a[1].localeCompare(b[1],lang)).map(([c,n])=>`<option value="${c}">${esc(n)}</option>`).join("");sel.value=S.code}
function toggleWish(code){const i=wish.indexOf(code);if(i>=0){wish.splice(i,1);toast(t("removedWish"))}else{wish.push(code);toast(t("addedWish"))}store.set("discoverWish",wish);renderSelected();renderWish()}
async function shareCountry(){const url=location.href.split(/[?#]/)[0]+"?c="+S.code+"#explore";try{if(navigator.share){await navigator.share({title:"DISCOVER — "+nm(S.code),url});return}}catch(e){if(e&&e.name==="AbortError")return}try{await navigator.clipboard.writeText(url);toast(t("linkCopied"))}catch(e){toast(url)}}

/* ---------- facts / content ---------- */
function currencyName(code,v){try{const dn=new Intl.DisplayNames([lang],{type:"currency"});return dn.of(code)||v.name}catch(e){return v.name}}
function renderFacts(d){const box=$("#countryFacts");if(!d){box.innerHTML="";return}const f=[];const nf=new Intl.NumberFormat(lang,{notation:"compact",maximumFractionDigits:1});
  if(d.capital&&d.capital.length)f.push(["capital",d.capital.slice(0,2).join(", ")]);
  if(d.subregion||d.region)f.push(["region",d.subregion||d.region]);
  if(d.population)f.push(["population",nf.format(d.population)]);
  if(d.area)f.push(["area",nf.format(d.area)+" km²"]);
  if(d.languages)f.push(["languagesF",Object.values(d.languages).slice(0,3).join(", ")]);
  if(d.currencies)f.push(["currencyF",Object.entries(d.currencies).slice(0,2).map(([c,v])=>currencyName(c,v)).join(", ")]);
  box.innerHTML=f.map(([k,v])=>`<div class="fact"><small>${t(k)}</small><b>${esc(v)}</b></div>`).join("")}
const gradient="linear-gradient(135deg,#14303c,#1c2b46)";
function setCover(u){const ov="linear-gradient(90deg,#07101aee,#07101a55 72%)";$("#countryBanner").style.backgroundImage=u?`${ov},url("${u}")`:`${ov},${gradient}`;$("#challengeImage").style.backgroundImage=u?`url("${u}")`:gradient}
function placeCard(p,i,country){const q=encodeURIComponent(`${p.title}, ${country}`);return `<a class="destination-card" href="https://www.google.com/maps/search/?api=1&query=${q}" target="_blank" rel="noopener" style="animation-delay:${i*70}ms"><div class="destination-image"><i class="di-fallback">${p.emoji||"✦"}</i>${p.img?`<img src="${esc(p.img)}" alt="${esc(p.title)}" loading="lazy" data-fix="${esc(p.title+" "+country)}">`:""}</div><div class="destination-info"><span>${esc(p.tag)}</span><h4>${esc(p.title)}</h4><p>${esc(p.text)}</p><em class="maps-link">${t("mapsLink")}</em></div></a>`}
function foodCard(f){return `<div class="food-card">${f.img?`<img class="food-thumb" src="${esc(f.img)}" alt="" loading="lazy">`:`<span class="food-emoji">${f.emoji}</span>`}<div><b>${esc(f.title)}</b><small>${esc(f.text)}</small></div></div>`}
function skeletons(n){return Array.from({length:n},()=>'<div class="skeleton"></div>').join("")}
function setPlaces(list,country){const grid=$("#destinationGrid");$("#placeCount").textContent=`${pad(list.length)} ${t("placesWord")}`;grid.innerHTML=list.map((p,i)=>placeCard(p,i,country)).join("")}
function mapsFallback(country){return [{title:country,tag:t("worthSeeing"),text:t("fallbackDesc"),emoji:"🗺️"}]}

async function renderContent(code,token){
  const cur=CURATED[code],name=nm(code),enName=BY_CODE[code].en;
  $("#bannerEyebrow").textContent=t("guide");$("#bannerTitle").textContent=name;$("#bannerNumber").textContent=pad(INDEX_OF[code]+1,3);
  $("#challengeCountryName").textContent=name;$("#challengeCountryLabel").textContent=`${name.toUpperCase()} · ${pad(INDEX_OF[code]+1)}`;
  S.desc=cur&&lang==="en"?cur.desc:"";$("#bannerDescription").textContent=S.desc;
  setCover(null);$("#countryFacts").innerHTML="";
  if(cur){setPlaces(cur.places.map(p=>({title:p[0],tag:p[1],text:p[2],img:IMAGE(p[3],850)})),enName);$("#foodBlock").hidden=false;$("#foodGrid").innerHTML=cur.food.map(f=>foodCard({emoji:f[0],title:f[1],text:f[2]})).join("")}
  else{$("#destinationGrid").innerHTML=skeletons(6);$("#placeCount").textContent="…";$("#foodBlock").hidden=false;$("#foodGrid").innerHTML=skeletons(4)}
  renderSelected();
  getDesc(code).then(d=>{if(token!==renderToken)return;S.desc=d;$("#bannerDescription").textContent=d;const sd=$("#selDesc");if(sd)sd.textContent=d});
  getFacts(code).then(d=>{if(token!==renderToken)return;renderFacts(d);if(d&&d.latlng){S.latlng[code]=d.latlng;if(!featByCode[code]&&globe)flyTo(code)}}).catch(()=>{});
  getCover(code).then(u=>{if(token===renderToken)setCover(u)}).catch(()=>{});
  if(!cur){
    getAttractions(code).then(list=>{if(token!==renderToken)return;setPlaces((list.length?list.map(p=>({...p,tag:t("worthSeeing")})):mapsFallback(name)),enName)}).catch(()=>{if(token===renderToken)setPlaces(mapsFallback(name),enName)});
    getFood(code).then(list=>{if(token!==renderToken)return;if(list.length){$("#foodGrid").innerHTML=list.map(foodCard).join("")}else $("#foodBlock").hidden=true}).catch(()=>{if(token===renderToken)$("#foodBlock").hidden=true});
  }
}
function setCountry(code,opts={}){
  if(!BY_CODE[code])return;
  const changed=code!==S.code;S.code=code;const token=++renderToken;store.set("discoverLast",code);
  if(!opts.silent){try{history.replaceState(null,"","?c="+code+location.hash)}catch(e){}}
  if(changed)resetChallengeForm();
  $("#countrySelect").value=code;
  renderChips();renderTasks();paintGlobe();
  renderContent(code,token);
  if(opts.fly!==false)flyTo(code);
}
function goCountry(code){setCountry(code);$("#explore").scrollIntoView({behavior:"smooth"})}

/* ---------- globe ---------- */
let globe=null,globeStarted=false,idleTimer=null;const featByCode={};
const GEO_URLS=["https://cdn.jsdelivr.net/gh/vasturiano/globe.gl@master/example/datasets/ne_110m_admin_0_countries.geojson","https://raw.githubusercontent.com/vasturiano/globe.gl/master/example/datasets/ne_110m_admin_0_countries.geojson","https://raw.githubusercontent.com/holtzy/D3-graph-gallery/master/DATA/world.geojson"];
function geoCode(f){const p=f.properties||{};let c=p.ISO_A2_EH;if(!c||c==="-99")c=p.ISO_A2;if(c&&c!=="-99"&&BY_CODE[c])return c;const n=p.ADMIN||p.NAME||p.name;if(n==="France")return"FR";if(n==="Norway")return"NO";if(NAME_ALIAS[n])return NAME_ALIAS[n];const m=n&&COUNTRY_LIST.find(x=>x.en.toLowerCase()===String(n).toLowerCase());return m?m.code:null}
async function loadGeo(){for(const u of GEO_URLS){try{const r=await fetch(u);if(!r.ok)continue;const j=await r.json();if(j.features&&j.features.length)return j.features}catch(e){}}throw Error("geo")}
function featureCenter(f){const g=f.geometry;if(!g)return null;const polys=g.type==="Polygon"?[g.coordinates]:g.coordinates;let best=polys[0],bn=0;polys.forEach(p=>{if(p[0].length>bn){bn=p[0].length;best=p}});let minX=180,maxX=-180,minY=90,maxY=-90;best[0].forEach(([x,y])=>{if(x<minX)minX=x;if(x>maxX)maxX=x;if(y<minY)minY=y;if(y>maxY)maxY=y});const span=Math.max(maxX-minX,(maxY-minY)*1.4);return{lat:(minY+maxY)/2,lng:(minX+maxX)/2,alt:Math.min(2.3,Math.max(.8,.7+span/40))}}
function paintGlobe(){if(!globe)return;const visited=new Set(getBook().map(b=>b.code));
  globe.polygonCapColor(f=>{const c=f.__code;if(c&&c===S.code)return"rgba(217,180,123,.92)";if(c&&c===S.hover)return"rgba(134,203,184,.55)";if(c&&visited.has(c))return"rgba(134,203,184,.38)";return"rgba(61,125,139,.2)"})
   .polygonAltitude(f=>f.__code&&f.__code===S.code?.045:(f.__code&&f.__code===S.hover?.02:.008))}
function stopAuto(){if(!globe)return;const c=globe.controls();c.autoRotate=false;clearTimeout(idleTimer);idleTimer=setTimeout(()=>{c.autoRotate=true},6000)}
function flyTo(code){if(!globe)return;let pos=null;const f=featByCode[code];if(f)pos=featureCenter(f);if(!pos&&S.latlng[code])pos={lat:S.latlng[code][0],lng:S.latlng[code][1],alt:1.2};if(!pos)return;stopAuto();globe.pointOfView({lat:pos.lat,lng:pos.lng,altitude:pos.alt},1200)}
async function initGlobe(){const host=$("#globeViz");
  const fail=()=>{host.innerHTML=`<div class="globe-loading">${esc(t("globeFail"))}</div>`;$("#globeStatus").textContent=""};
  if(typeof Globe!=="function")return fail();
  let feats;try{feats=await loadGeo()}catch(e){return fail()}
  feats.forEach(f=>{f.__code=geoCode(f);if(f.__code&&!featByCode[f.__code])featByCode[f.__code]=f});
  host.innerHTML="";
  globe=Globe()(host).width(host.clientWidth).height(host.clientHeight).backgroundColor("rgba(0,0,0,0)")
    .globeImageUrl("https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg").bumpImageUrl("https://unpkg.com/three-globe/example/img/earth-topology.png")
    .showAtmosphere(true).atmosphereColor("#75c9d1").atmosphereAltitude(.18)
    .polygonsData(feats).polygonSideColor(()=>"rgba(50,110,125,.12)").polygonStrokeColor(()=>"rgba(190,215,220,.25)").polygonsTransitionDuration(300)
    .polygonLabel(f=>f.__code?`<div class="globe-tip">${flagEmoji(f.__code)} ${esc(nm(f.__code))}</div>`:`<div class="globe-tip">${esc(f.properties?.ADMIN||f.properties?.name||"")}</div>`)
    .onPolygonHover(f=>{S.hover=f?f.__code:null;host.style.cursor=f&&f.__code?"pointer":"grab";paintGlobe()})
    .onPolygonClick(f=>{if(f&&f.__code)goCountry(f.__code);else if(f)toast(f.properties?.ADMIN||f.properties?.name||"")});
  const c=globe.controls();c.autoRotate=true;c.autoRotateSpeed=.35;c.enableDamping=true;
  globe.pointOfView({lat:25,lng:12,altitude:2.3});
  host.addEventListener("pointerdown",stopAuto);host.addEventListener("wheel",stopAuto,{passive:true});
  new ResizeObserver(()=>{if(globe)globe.width(host.clientWidth).height(host.clientHeight)}).observe(host);
  $("#globeStatus").textContent=t("globeReady");paintGlobe();setTimeout(()=>flyTo(S.code),500)}
function whenGlobeReady(cb){if(typeof Globe==="function")cb();else window.addEventListener("load",cb,{once:true})}
if("IntersectionObserver"in window){new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!globeStarted){globeStarted=true;whenGlobeReady(initGlobe)}if(globe){e.isIntersecting?globe.resumeAnimation():globe.pauseAnimation()}}),{rootMargin:"300px"}).observe($("#globeViz"))}else whenGlobeReady(initGlobe);

/* ---------- search ---------- */
const inp=$("#countrySearch"),resBox=$("#searchResults");let sIdx=-1,sRes=[];
function searchCountries(q){q=norm(q.trim());if(!q)return[];return COUNTRY_LIST.map(c=>({c:c.code,n:norm(nm(c.code)),e:norm(c.en)})).filter(x=>x.n.includes(q)||x.e.includes(q)).sort((a,b)=>((b.n.startsWith(q)||b.e.startsWith(q))?1:0)-((a.n.startsWith(q)||a.e.startsWith(q))?1:0)).slice(0,6).map(x=>x.c)}
function renderSearch(){if(!inp.value.trim()){closeSearch();return}sRes=searchCountries(inp.value);resBox.innerHTML=sRes.length?sRes.map((c,i)=>`<li role="presentation"><button type="button" role="option" id="sr-${i}" data-code="${c}" aria-selected="${i===sIdx}">${flagImg(c)}<span>${esc(nm(c))}</span></button></li>`).join(""):`<li class="search-empty">${t("noResults")}</li>`;resBox.hidden=false;inp.setAttribute("aria-expanded","true");inp.setAttribute("aria-activedescendant",sIdx>=0?"sr-"+sIdx:"")}
function closeSearch(){resBox.hidden=true;sIdx=-1;inp.setAttribute("aria-expanded","false")}
function pickSearch(code){inp.value="";closeSearch();goCountry(code)}
inp.addEventListener("input",()=>{sIdx=-1;renderSearch()});
inp.addEventListener("focus",()=>{if(inp.value.trim())renderSearch()});
inp.addEventListener("keydown",e=>{if(e.key==="ArrowDown"||e.key==="ArrowUp"){if(!sRes.length)return;e.preventDefault();sIdx=(sIdx+(e.key==="ArrowDown"?1:-1)+sRes.length)%sRes.length;renderSearch()}
  else if(e.key==="Enter"){const c=sRes[sIdx>=0?sIdx:0];if(c){e.preventDefault();pickSearch(c)}}
  else if(e.key==="Escape")closeSearch()});
resBox.addEventListener("click",e=>{const b=e.target.closest("button[data-code]");if(b)pickSearch(b.dataset.code)});
document.addEventListener("click",e=>{if(!e.target.closest(".searchwrap"))closeSearch()});
const pickChip=e=>{const b=e.target.closest("button[data-code]");if(b)goCountry(b.dataset.code)};
$("#popularCountries").addEventListener("click",pickChip);$("#wishlist").addEventListener("click",pickChip);
$("#countrySelect").addEventListener("change",e=>goCountry(e.target.value));
$("#surpriseBtn").addEventListener("click",()=>{let c;do{c=COUNTRY_LIST[Math.random()*COUNTRY_LIST.length|0].code}while(c===S.code);goCountry(c)});
$("#selectedCountry").addEventListener("click",e=>{const b=e.target.closest("[data-act]");if(!b)return;if(b.dataset.act==="wish")toggleWish(S.code);else shareCountry()});

/* ---------- photos ---------- */
function compress(file,max=1200,q=.8){return new Promise((res,rej)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{let w=img.naturalWidth,h=img.naturalHeight;const k=Math.min(1,max/Math.max(w,h));w=Math.round(w*k);h=Math.round(h*k);const c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(img,0,0,w,h);URL.revokeObjectURL(url);res(c.toDataURL("image/jpeg",q))};img.onerror=()=>{URL.revokeObjectURL(url);rej(new Error("img"))};img.src=url})}

/* ---------- challenge + travel book ---------- */
function resetChallengeForm(){memoryData="";$("#memoryPhoto").value="";$("#memoryPhotoName").textContent=t("noPhoto");$("#memoryNote").value=""}
function renderTasks(){const all=store.get("discoverTasks",{});taskState=all[S.code]||[false,false,false,false];$("#challengeTasks").innerHTML=[1,2,3,4].map((n,i)=>`<label class="task"><input type="checkbox" data-task="${i}" ${taskState[i]?"checked":""}>${esc(t("task"+n))}</label>`).join("");updateChallenge()}
$("#challengeTasks").addEventListener("change",e=>{const inp=e.target.closest("input[data-task]");if(!inp)return;taskState[+inp.dataset.task]=inp.checked;const all=store.get("discoverTasks",{});all[S.code]=taskState;store.set("discoverTasks",all);updateChallenge()});
function updateChallenge(){const done=taskState.filter(Boolean).length;$("#challengePercent").textContent=Math.round(done/4*100)+"%";$("#completeCountryBtn").disabled=done!==4||!memoryData}
function updateProgress(){const n=getBook().length;$("#progressText").textContent=`${n} / ${COUNTRY_LIST.length} ${t("countries")}`;$("#progressBar").style.width=Math.min(100,n/COUNTRY_LIST.length*100)+"%"}
function renderBook(){const book=getBook();$("#bookEntries").innerHTML=book.length?book.map(x=>`<div class="book-entry" data-code="${x.code}" tabindex="0" role="button"><img src="${x.photo}" alt=""><div><b>${esc(nm(x.code))}</b><small>${esc(x.date||"")}</small>${x.note?`<p>${esc(x.note)}</p>`:""}</div><button type="button" class="rm" data-rm="${x.code}" aria-label="${esc(t("del"))}">×</button></div>`).join(""):`<div class="empty-book">${t("emptyBook")}</div>`;updateProgress();paintGlobe()}
$("#bookEntries").addEventListener("click",e=>{const rm=e.target.closest("[data-rm]");if(rm){e.stopPropagation();if(confirm(t("confirmDel"))){store.set("discoverBook",getBook().filter(x=>x.code!==rm.dataset.rm));renderBook()}return}const en=e.target.closest(".book-entry");if(en)goCountry(en.dataset.code)});
$("#bookEntries").addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.classList.contains("book-entry")){e.preventDefault();goCountry(e.target.dataset.code)}});
$("#memoryPhoto").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;try{memoryData=await compress(f);$("#memoryPhotoName").textContent=f.name}catch(err){memoryData="";e.target.value="";toast(t("photoError"))}updateChallenge()});
$("#completeCountryBtn").addEventListener("click",()=>{const book=getBook();if(book.some(x=>x.code===S.code)){toast(t("inBook"));return}
  book.unshift({code:S.code,name:BY_CODE[S.code].en,photo:memoryData,note:$("#memoryNote").value.trim(),date:new Date().toLocaleDateString(lang),ts:Date.now()});
  if(!store.set("discoverBook",book)){toast(t("storageFull"));return}
  const all=store.get("discoverTasks",{});delete all[S.code];store.set("discoverTasks",all);
  resetChallengeForm();renderBook();renderTasks();toast(t("bookAdded"));confetti()});
function confetti(){if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;const c=$("#confetti"),x=c.getContext("2d");c.width=innerWidth;c.height=innerHeight;const cols=["#d9b47b","#86cbb8","#f4f0e8","#e07a5f"];const ps=Array.from({length:120},()=>({x:innerWidth/2,y:innerHeight*.6,vx:(Math.random()-.5)*14,vy:-Math.random()*15-4,s:4+Math.random()*5,c:cols[Math.random()*4|0],r:Math.random()*6,vr:(Math.random()-.5)*.4}));let f=0;(function step(){x.clearRect(0,0,c.width,c.height);ps.forEach(p=>{p.vy+=.35;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/2,p.s,p.s*.6);x.restore()});if(++f<130)requestAnimationFrame(step);else x.clearRect(0,0,c.width,c.height)})()}

/* ---------- moments ---------- */
const DEFAULT_POSTS=[{id:"d1",user:"discover.travel",location:"Kyoto, Japan",caption:"Quiet mornings and timeless streets. 🍃",photo:IMAGE("photo-1493976040374-85c8e12f0c0e",900),likes:128},{id:"d2",user:"wander.notes",location:"Amalfi Coast, Italy",caption:"A little colour along the coast.",photo:IMAGE("photo-1533587851505-d119e13fa0d7",900),likes:94},{id:"d3",user:"earth.seeker",location:"Marrakech, Morocco",caption:"Textures, light and stories in every corner.",photo:IMAGE("photo-1489749798305-4fea3ae63d43",900),likes:211}];
const STORIES=[["Your story","photo-1534528741775-53994a69daeb",null],["Tokyo","photo-1540959733332-eab4deabeeaf","JP"],["Sahara","photo-1509316785289-025f5b846b35","MA"],["Italy","photo-1516483638261-f4dbaf036963","IT"],["Coast","photo-1500375592092-40eb2168fd21","GR"]];
function renderStories(){$("#storiesRow").innerHTML=STORIES.map((s,i)=>`<button type="button" class="story" data-story="${i}"><div class="story-ring"><img src="${IMAGE(s[1],150)}" alt="" loading="lazy"></div><small>${s[2]?esc(nm(s[2])):esc(t("addPhoto"))}</small></button>`).join("")}
$("#storiesRow").addEventListener("click",e=>{const b=e.target.closest("[data-story]");if(!b)return;const s=STORIES[+b.dataset.story];if(s[2])goCountry(s[2]);else $("#postPhotoInput").click()});
const postState=()=>store.get("discoverPostState",{liked:{},saved:{}});
function renderFeed(){const st=postState();let list=[...store.get("discoverMyPosts",[]),...DEFAULT_POSTS];if(feedFilter==="saved")list=list.filter(p=>st.saved[p.id]);if(feedFilter==="mine")list=list.filter(p=>p.mine);
  $("#feedGrid").innerHTML=list.length?list.map(p=>{const liked=!!st.liked[p.id],saved=!!st.saved[p.id];return `<article class="post-card"><img class="post-image" src="${p.photo}" alt="${esc(p.caption||"")}" loading="lazy" data-lightbox data-id="${p.id}"><div class="post-meta"><div class="post-user"><b>@${esc(p.user)}</b></div><div class="post-location">⌖ ${esc(p.location||"—")}</div><p class="post-caption">${esc(p.caption||"")}</p><div class="post-actions"><button type="button" class="${liked?"liked":""}" data-like="${p.id}" aria-pressed="${liked}">${liked?"♥":"♡"} ${(p.likes||0)+(liked?1:0)}</button><button type="button" class="${saved?"on":""}" data-save="${p.id}" aria-pressed="${saved}">${saved?"★":"☆"} ${t(saved?"saved":"save")}</button>${p.mine?`<button type="button" class="danger spacer" data-del="${p.id}">${t("del")}</button>`:""}</div></div></article>`}).join(""):`<p class="feed-empty">${t("emptyFeed")}</p>`;
  $$("#feedTools button").forEach(b=>b.classList.toggle("active",b.dataset.filter===feedFilter))}
function toggleState(kind,id){const st=postState();st[kind][id]=!st[kind][id];if(!st[kind][id])delete st[kind][id];store.set("discoverPostState",st);renderFeed()}
$("#feedGrid").addEventListener("click",e=>{const l=e.target.closest("[data-like]"),s=e.target.closest("[data-save]"),d=e.target.closest("[data-del]"),im=e.target.closest("[data-lightbox]");
  if(l)toggleState("liked",l.dataset.like);else if(s)toggleState("saved",s.dataset.save);
  else if(d){if(confirm(t("confirmDel"))){store.set("discoverMyPosts",store.get("discoverMyPosts",[]).filter(p=>p.id!==d.dataset.del));renderFeed()}}
  else if(im)openLightbox(im.src,im.alt)});
$("#feedGrid").addEventListener("dblclick",e=>{const im=e.target.closest("[data-lightbox]");if(im){const st=postState();if(!st.liked[im.dataset.id])toggleState("liked",im.dataset.id)}});
$("#feedTools").addEventListener("click",e=>{const b=e.target.closest("[data-filter]");if(b){feedFilter=b.dataset.filter;renderFeed()}});
function openLightbox(src,alt){const lb=$("#lightbox");$("img",lb).src=src;$("img",lb).alt=alt||"";lb.classList.add("open");lb.setAttribute("aria-hidden","false")}
function closeLightbox(){const lb=$("#lightbox");lb.classList.remove("open");lb.setAttribute("aria-hidden","true")}
$("#lightbox").addEventListener("click",e=>{if(e.target.id==="lightbox"||e.target.closest("[data-close=lightbox]"))closeLightbox()});
function openModal(){const m=$("#postModal");m.classList.add("open");m.setAttribute("aria-hidden","false");setTimeout(()=>$("#postCaption").focus(),50)}
function closeModal(){const m=$("#postModal");m.classList.remove("open");m.setAttribute("aria-hidden","true")}
$("#addPostBtn").onclick=()=>$("#postPhotoInput").click();
$("#postPhotoInput").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;try{postPhotoData=await compress(f);$("#postPreview").src=postPhotoData;openModal()}catch(err){postPhotoData="";toast(t("photoError"))}e.target.value=""});
$("#publishPostBtn").onclick=()=>{if(!postPhotoData){toast(t("needPhoto"));return}const mine=store.get("discoverMyPosts",[]);mine.unshift({id:"u"+Date.now(),user:"you",mine:true,location:$("#postLocation").value.trim()||"—",caption:$("#postCaption").value.trim(),photo:postPhotoData,likes:0});
  if(!store.set("discoverMyPosts",mine)){toast(t("storageFull"));return}
  closeModal();$("#postCaption").value="";$("#postLocation").value="";postPhotoData="";feedFilter="all";renderFeed();toast(t("posted"))};
$$("[data-close=modal]").forEach(el=>el.addEventListener("click",closeModal));

/* ---------- chrome: nav, scroll, language, keyboard ---------- */
$("#languageSelect").addEventListener("change",e=>{lang=e.target.value;store.set("discoverLang",lang);applyLanguage();populateSelect();renderStories();renderFeed();renderBook();closeSearch();setCountry(S.code,{fly:false,silent:true});if(globe)$("#globeStatus").textContent=t("globeReady");document.body.classList.add("transitioning");setTimeout(()=>document.body.classList.remove("transitioning"),550)});
$("#menuBtn").onclick=()=>{const o=$("#mainNav").classList.toggle("open");$("#menuBtn").setAttribute("aria-expanded",o)};
$$(".main-nav a").forEach(a=>a.addEventListener("click",()=>{$("#mainNav").classList.remove("open");$("#menuBtn").setAttribute("aria-expanded","false")}));
$$('a[href^="#"]').forEach(a=>a.addEventListener("click",()=>{document.body.classList.add("transitioning");setTimeout(()=>document.body.classList.remove("transitioning"),550)}));
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();closeLightbox();closeSearch()}});
let ticking=false;
addEventListener("scroll",()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const h=document.documentElement,max=h.scrollHeight-innerHeight;$("#scrollProgress").style.width=(max>0?scrollY/max*100:0)+"%";$("#toTop").classList.toggle("show",scrollY>800);ticking=false})},{passive:true});
$("#toTop").onclick=()=>scrollTo({top:0,behavior:"smooth"});
if("IntersectionObserver"in window){
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");io.unobserve(e.target)}}),{threshold:.12});$$(".reveal").forEach(el=>io.observe(el));
  const links=$$(".main-nav a"),map={home:"#home",world:"#explore",explore:"#explore",moments:"#moments",book:"#book"};
  const so=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle("active",a.getAttribute("href")===map[e.target.id]))}}),{rootMargin:"-40% 0px -55% 0px"});
  $$("main > section").forEach(s=>so.observe(s));
}else $$(".reveal").forEach(el=>el.classList.add("visible"));
function countUp(){const el=$("#heroCount"),end=COUNTRY_LIST.length;if(matchMedia("(prefers-reduced-motion: reduce)").matches){el.textContent=end;return}const t0=performance.now();(function f(n){const p=Math.min(1,(n-t0)/1200);el.textContent=Math.round(end*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(f)})(t0)}

/* ---------- storage migration from the previous version ---------- */
function migrate(){if(store.get("discoverV",0)>=2)return;
  const book=store.get("discoverBook",[]).map(e=>({...e,code:e.code||legacyCode(e.key||e.name)})).filter(e=>e.code);if(localStorage.getItem("discoverBook")!==null)store.set("discoverBook",book);
  const tasks=store.get("discoverTasks",{}),nt={};Object.keys(tasks).forEach(k=>{const c=BY_CODE[k]?k:legacyCode(k);if(c)nt[c]=tasks[k]});if(localStorage.getItem("discoverTasks")!==null)store.set("discoverTasks",nt);
  const old=store.get("discoverPosts",null);if(Array.isArray(old)){const mine=old.filter(p=>p&&p.user==="you").map((p,i)=>({...p,id:"u"+Date.now()+i,mine:true}));if(mine.length&&!store.get("discoverMyPosts",null))store.set("discoverMyPosts",mine);try{localStorage.removeItem("discoverPosts")}catch(e){}}
  store.set("discoverV",2)}

/* ---------- boot ---------- */
migrate();
$("#heroLabel").textContent=`01 / ${COUNTRY_LIST.length}`;
const qp=(new URLSearchParams(location.search).get("c")||"").toUpperCase(),last=store.get("discoverLast","TN");
S.code=BY_CODE[qp]?qp:(BY_CODE[last]?last:"TN");
applyLanguage();populateSelect();renderStories();renderFeed();renderBook();
setCountry(S.code,{fly:false,silent:true});
countUp();
